import { Spark, StackedDayBars, Swimlane, TelemetryPanel, SplitBar, type StackedDay, type SwimLane, type SwimEvent } from "@/shared/ui/charts";

interface LegendNode { label: string; color: string }
interface LegendSection { label: string; nodes: LegendNode[] }
function GraphLegend({ sections }: { sections: LegendSection[] }) {
  return (
    <div style={{ position: "absolute", right: 16, bottom: 16, zIndex: 3, pointerEvents: "none", display: "flex", gap: 20, padding: "11px 14px", borderRadius: 9, border: "1px solid var(--border)", background: "color-mix(in oklch, var(--bg-elev) 85%, transparent)", backdropFilter: "blur(8px)" }}>
      {sections.map((s) => (
        <div key={s.label} style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <span className="mono" style={{ fontSize: 9, letterSpacing: ".08em", textTransform: "uppercase", color: "var(--fg-dim)" }}>{s.label}</span>
          {s.nodes.map((n) => (
            <div key={n.label} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ width: 8, height: 8, borderRadius: 2, background: n.color, flex: "none", display: "inline-block" }} />
              <span style={{ fontSize: 11.5 }}>{n.label}</span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

const DEMO_STACKED: StackedDay[] = [
  { day: "2026-07-14", upper: 12, lower: 6 }, { day: "2026-07-15", upper: 18, lower: 4 }, { day: "2026-07-16", upper: 9, lower: 11 },
  { day: "2026-07-17", upper: 22, lower: 5 }, { day: "2026-07-18", upper: 15, lower: 8 }, { day: "2026-07-19", upper: 19, lower: 3 }, { day: "2026-07-20", upper: 14, lower: 7 },
];
const DEMO_LANES: SwimLane[] = [{ name: "build" }, { name: "test" }, { name: "deploy" }];
const DEMO_EVENTS: SwimEvent[] = [
  { lane: 0, t0: 0.05, t1: 0.35, color: "var(--accent)", label: "build" },
  { lane: 1, t0: 0.35, t1: 0.7, color: "var(--info)", label: "test" },
  { lane: 2, t0: 0.7, t1: 0.92, color: "var(--success)", label: "deploy" },
];

export function TelemetryGalleryPage() {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16, padding: 20 }}>
      <StackedDayBars data={DEMO_STACKED} title="hook calls / day" subtitle="last 7 days" upperLabel="done" lowerLabel="blocked" />
      <TelemetryPanel title="outcomes" hint="pass / fail">
        <SplitBar label="outcomes" a={82} b={14} aLabel="passed" bLabel="failed" />
      </TelemetryPanel>
      <TelemetryPanel title="pipeline timeline" hint="build to deploy">
        <div style={{ position: "relative" }}>
          <Swimlane lanes={DEMO_LANES} events={DEMO_EVENTS} />
          <GraphLegend sections={[{ label: "stage", nodes: [{ label: "build", color: "var(--accent)" }, { label: "test", color: "var(--info)" }, { label: "deploy", color: "var(--success)" }] }]} />
        </div>
      </TelemetryPanel>
      <TelemetryPanel title="commit trend" hint="sparkline">
        <Spark data={[4, 7, 5, 9, 6, 10, 8]} color="var(--accent)" w={200} h={40} />
      </TelemetryPanel>
    </div>
  );
}

